arguments.command:
cd /app && PYTHONPATH=categorizationapp python3 << 'EOF'
import pandas as pd
from categorizationapp.BankScripts.Canara import categorize_Canara_transactions
from categorizationapp.BankScripts.PNB import categorize_PNB_transactions
from categorizationapp.BankScripts.AuSmallFinanceBank import categorize_AuSmallFinance_transactions
from categorizationapp.BankScripts.HDFC import categorize_HDFC_transactions
from categorizationapp.BankScripts.ICICI import categorize_ICICI_transactions
from categorizationapp.BankScripts.SBI import categorize_SBI_transactions

def run(fn, rows, bank):
    df = pd.DataFrame(rows)
    for c in ['remark','balanceAfterTransaction']:
        if c not in df: df[c] = ''
    if 'balanceAfterTransaction' in df:
        df['balanceAfterTransaction'] = 0
    out = fn(df, 'SAVING')
    print(f'\n=== {bank} ===')
    for i, r in out.iterrows():
        print(f"  desc={rows[i]['description'][:60]!r} remark={rows[i].get('remark','')!r}")
        print(f"  -> cat={r['transactionCategory']} party={r['partyName']!r}")

# F-2
run(categorize_Canara_transactions, [{
    'description': 'CHQ PAID-MICR CLG-RAVI KUMAR',
    'amount': 5000, 'type': 'DEBIT', 'remark': ''
}], 'Canara F-2')

run(categorize_AuSmallFinance_transactions, [{
    'description': 'CHQ PAID-MICR CLG-RAVI KUMAR',
    'amount': 5000, 'type': 'DEBIT', 'remark': ''
}], 'Au F-2')

run(categorize_HDFC_transactions, [{
    'description': 'CHQ PAID-MICR CLG-RAVI KUMAR',
    'amount': 5000, 'type': 'DEBIT', 'remark': ''
}], 'HDFC F-2')

# F-5
run(categorize_Canara_transactions, [{
    'description': 'IMPS Txn is this account live',
    'amount': 1, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'is this account live',
    'amount': 1, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'Account validation penny drop',
    'amount': 1, 'type': 'CREDIT', 'remark': ''
}], 'Canara F-5')

# F-1
run(categorize_Canara_transactions, [{
    'description': 'TO TRANSFER',
    'amount': 1000, 'type': 'DEBIT', 'remark': '123456'
}, {
    'description': 'SOME PAYEE',
    'amount': 1000, 'type': 'DEBIT', 'remark': '12345'
}], 'Canara F-1')

run(categorize_PNB_transactions, [{
    'description': 'TO TRF',
    'amount': 1000, 'type': 'DEBIT', 'remark': '123456'
}, {
    'description': 'TO TRF',
    'amount': 1000, 'type': 'DEBIT', 'remark': '12345'
}], 'PNB F-1')

# F-3 NEFT
run(categorize_Canara_transactions, [{
    'description': 'NEFT-SBIN123456789012-JOHN DOE-REF',
    'amount': 5000, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'NEFT Cr-SBIN123456789-PRIYA SHARMA',
    'amount': 5000, 'type': 'CREDIT', 'remark': ''
}], 'Canara F-3 NEFT')

run(categorize_ICICI_transactions, [{
    'description': 'INF/NEFT/SBIN123456789/SBIN0001234/JOHN DOE',
    'amount': 5000, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'INF/NEFT/UTR123/NAME ONLY',
    'amount': 5000, 'type': 'CREDIT', 'remark': ''
}], 'ICICI F-3 NEFT')

# F-4 UPI/IMPS
run(categorize_Canara_transactions, [{
    'description': 'UPI/CR/420212345678/AMIT SHAH/SBIN/Pay',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'MB-IMPS- CR/420212345678/AMIT SHAH/HDFC',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'UPI/CR/AMIT SHAH/SBIN/Pay',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}], 'Canara F-4')

run(categorize_PNB_transactions, [{
    'description': 'UPI/420212345678/P2A/AMIT SHAH/SBIN',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'UPI/xxx/yyy/P2A/AMIT SHAH/SBIN',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}], 'PNB F-4')

run(categorize_SBI_transactions, [{
    'description': 'UPI/420212345678/CR/AMIT SHAH/SBIN',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}, {
    'description': 'UPI/something/AMIT SHAH/SBIN/xxx',
    'amount': 500, 'type': 'CREDIT', 'remark': ''
}], 'SBI F-4')

# Sanity: ordinary transfer unchanged-ish
run(categorize_Canara_transactions, [{
    'description': 'Funds Transfer to RAMESH',
    'amount': 10000, 'type': 'DEBIT', 'remark': ''
}, {
